func sanitizeTaskKeyPath(taskKey string) string {
	taskKey = strings.TrimSpace(taskKey)
	if taskKey == "" {
		return "TASK-DEFAULT"
	}
	var b strings.Builder
	for _, r := range taskKey {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '-' || r == '_' || r == '.' {
			b.WriteRune(r)
		} else {
			b.WriteRune('-')
		}
	}
	res := strings.Trim(b.String(), "-")
	if res == "" {
		return "TASK-DEFAULT"
	}
	return res
}

